INSERT INTO `causaciones` (`id`, `id_factura`, `id_contrato`, `estado`, `sugerencia`, `fecha_causacion`) VALUES (11,'933bae1ca6ed3b8c9b1d09a939da0a61353314b9','CT-03','rechazada','Estado: RECHAZADA\nExplicación: El valor facturado de 6.604.500,00 no coincide con el valor esperado del período trimestral de 17.612.000,00 según términos contractuales. Se requiere verificar si existe un desglose parcial no documentado o ajustar la factura al monto trimestral establecido en el contrato antes de proceder con el pago.','2026-11-13 01:41:47'),(12,'19ae3e8e5df28fb36d4e020e267318b40af47f49','CT-03','validada','Estado: APROBADA\nExplicación: La factura ha superado todas las validaciones requeridas, incluyendo verificaciones matemáticas, concordancia de ítems y cumplimiento de los topes contractuales establecidos. No se identificaron discrepancias frente al contrato. Se autoriza el procesamiento y pago de la factura.','2026-11-13 01:44:56'),(13,'3a37dfe702393e0fa6c8bbc2a299e490bbed2cf3','CT-01','validada','Estado: APROBADA\nExplicación: La factura ha superado satisfactoriamente todas las validaciones requeridas, incluyendo verificaciones matemáticas, validación de ítems y conformidad con los topes contractuales establecidos. No se han identificado discrepancias y el documento es apto para procesamiento.','2026-11-13 02:51:28'),(14,'03c2580123a49f7ae7c7ad1f75e63fcf0f6c1e49','CT-02','rechazada','Estado: RECHAZADA\nExplicación: El valor de la factura por 14280000.0 no coincide con el valor estipulado para el período anual de 120000000.0 según lo establecido en el contrato. Se recomienda solicitar al proveedor la emisión de una nota crédito y la corrección de la factura para que el monto refleje exactamente el valor correspondiente al período contractual.','2026-11-13 03:33:56');

